<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
  <main class="gal-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="gal-opbar"><button @click="emit('back')">←</button><strong>GALLERIA</strong><span>LUXURY HALL</span><div><button data-testid="shopping-open-service" @click="emit('open-service')">CONCIERGE</button><button @click="emit('open-orders')">SERVICES</button><button @click="emit('open-cart')">REQUEST <b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="gal-request"><header><div class="gal-seal">G</div><article><span>CONCIERGE REQUEST / PRIVATE REVIEW</span><h1>{{ l('购买之前，先安排鉴赏与服务','Arrange viewing and service before purchase') }}</h1><p>{{ l('礼宾申请单管理看款、礼赠呈现和专属配送，而不是普通购物车。','The concierge request manages viewing, gift presentation, and private delivery rather than behaving like a standard cart.') }}</p></article></header><section class="gal-service-strip"><div><i class="fas fa-eye"></i><span>PRIVATE VIEW</span></div><div><i class="fas fa-gift"></i><span>PRESENTATION</span></div><div><i class="fas fa-car-side"></i><span>DELIVERY</span></div></section><div v-if="!cartItems.length" class="gal-empty">NO CONCIERGE REQUESTS</div><div v-else class="gal-request-layout"><section><article v-for="(line,index) in cartItems" :key="line.productId"><span class="gal-piece"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>SALON {{ String(index+1).padStart(2,'0') }}</em></span><div><small>CURATOR SELECTION</small><strong>{{ productDisplayTitle(line.product) }}</strong><p>{{ l('看款与包装方式将在礼宾确认中完成','Viewing and presentation are completed during concierge review') }}</p><b>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</b><div><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><span>PRIVATE REQUEST</span><strong>{{ cartTotalLabel }}</strong><blockquote>{{ l('“服务不是附加项，而是这次购买的一部分。”','“Service is not an add-on; it is part of the purchase.”') }}</blockquote><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" /> GIFT PRESENTATION</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">MANUAL RECIPIENT</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">SUBMIT CONCIERGE REQUEST</button></aside></div></section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="gal-services"><header><div><span>PRIVATE SERVICE RECORDS</span><h1>{{ l('礼宾与私人服务记录','Concierge & private service records') }}</h1></div><button @click="emit('open-logistics')">PRIVATE DELIVERY →</button></header><article v-for="(order,index) in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><div class="gal-service-no"><span>SERVICE</span><b>{{ String(index+1).padStart(2,'0') }}</b></div><div><small>{{ formatLogisticsDate(order.createdAt) }}</small><h2>{{ order.items.map(x=>x.title).join(' / ') }}</h2><p>{{ order.itemCount }} PIECES · {{ formatOrderTotal(order) }}</p><em>{{ orderStatusLabel(order.status) }}</em></div><button :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">OPEN SERVICE</button><button @click="emit('delete-order',order.id)">×</button></article><div v-if="!orders.length" class="gal-empty">NO PRIVATE SERVICES</div></section>
    <section v-else-if="pageKey==='logistics'" class="gal-delivery" data-testid="shopping-logistics-panel"><header><button @click="emit('open-orders')">← SERVICES</button><span>PRIVATE DELIVERY</span><h1>{{ l('包装、承运与交付礼仪','Presentation, carrier, and delivery protocol') }}</h1></header><article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><div class="gal-delivery-seal"><i class="fas fa-gem"></i></div><div><small>{{ row.latestEvent?logisticsEventTypeLabel(row.latestEvent.type):'CONCIERGE PREPARING' }}</small><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary||row.summary }}</p><b :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</b><em v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ [row.latestEvent.carrierName,row.latestEvent.trackingCode,row.latestEvent.locationHint].filter(Boolean).join(' / ') }}</em></div><button :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order',row.order.id)">OPEN SERVICE</button></article><div v-if="!logisticsRows.length" class="gal-empty">NO PRIVATE DELIVERY RECORDS</div></section>
    <section v-else-if="selectedOrder" class="gal-detail" data-testid="shopping-order-detail-panel"><header><button data-testid="shopping-close-order-detail" @click="emit('close-order')">←</button><div><span>PRIVATE SERVICE DOSSIER</span><h1>{{ selectedOrder.id }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="gal-detail-hall"><div class="gal-seal">G</div><article><span>SERVICE VALUE</span><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong><h2>{{ selectedOrder.items.map(x=>x.title).join(' / ') }}</h2><p>{{ selectedOrder.itemCount }} PIECES / CONCIERGE REVIEW</p></article></section><section class="gal-detail-items"><article v-for="(item,index) in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span>SALON {{ String(index+1).padStart(2,'0') }}</span><div><h3>{{ item.title }}</h3><p>PRIVATE VIEW / PRESENTATION REVIEW</p></div><strong>{{ formatOrderItemSubtotal(item) }}</strong></article></section><section class="gal-detail-timeline" data-testid="shopping-order-detail-timeline"><h2>CONCIERGE NOTES</h2><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><span>{{ formatLogisticsDate(event.createdAt) }}</span><b>{{ logisticsEventTypeLabel(event.type) }}</b><p>{{ event.summary||event.title }}</p></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO CONCIERGE EVENTS</p></section><footer><button data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">COMPLETE SERVICE</button><button data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">CANCEL REQUEST</button><button data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">DELETE RECORD</button></footer></section>
  </main>
